"use strict";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { useGaugeAPR, useGaugeStaking } from "hooks/useGaugeStaking";
import { useTradingFeeRewards } from "hooks/useTradingFeeRewards";
import styled from "styled-components";
import { Flex, Separator, Text, styled as UiStyled, useSporeColors } from "ui/src";
import { formatCurrencyAmount } from "utils/formatCurrencyAmount";
export default function StakedUnstakedAprEmissionsTradingFees({
  position,
  isLoading
}) {
  const colors = useSporeColors();
  const gaugeData = useGaugeStaking(position);
  const { apr: gaugeAPR, isLoading: aprLoading } = useGaugeAPR(position?.poolId);
  const isGaugePosition = position?.isGaugePosition;
  const feeData = useTradingFeeRewards(position);
  const GridItem = UiStyled(Flex, {
    backgroundColor: "$slate",
    p: "$spacing12",
    borderRadius: "$rounded12"
  });
  const TextWrapper = UiStyled(Text, {
    variant: "body2"
  });
  const Button = styled.div`
    all: unset;
    padding: 8px 8px;
    background-color: ${colors.surface2.val};
    border-radius: 10px;
    border: 1px solid ${colors.surface3.val};
    transition: all 0.2s ease;
    cursor: pointer;
    display: flex;
    justify-content: center;
    align-items: center;
    &:hover {
      background-color: ${colors.surface2Hovered.val};
    }
  `;
  return <Flex
    $platform-web={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr" }}
    $md={{ gridTemplateColumns: "1fr" }}
    gap={"$gap12"}
  >
      {(gaugeData.gaugeAddress || true) && // TEMP: Always show for debugging
  <GridItem $platform-web={{ display: "grid", gridTemplateColumns: "1fr 1fr" }} $md={{ display: "flex" }}>
          <Flex className="staked">
            <Text variant="buttonLabel4" color={"$neutral2"}>
              Staked
            </Text>
            <Flex mt={"$spacing12"} flexDirection="column" gap={"$gap4"}>
              <TextWrapper>
                {isGaugePosition ? formatCurrencyAmount(position?.currency0Amount, 4) : gaugeData.stakedAmount0}{" "}
                {position?.currency0Amount?.currency.symbol || "Token0"}
              </TextWrapper>
              <TextWrapper>
                {isGaugePosition ? formatCurrencyAmount(position?.currency1Amount, 4) : gaugeData.stakedAmount1}{" "}
                {position?.currency1Amount?.currency.symbol || "Token1"}
              </TextWrapper>
            </Flex>
          </Flex>{" "}
          <Flex className="unstaked" row $md={{ flexDirection: "column", width: "100%" }}>
            <Separator
    vertical={true}
    height={"100%"}
    width={1}
    borderColor={"$surface3"}
    mr={"$spacing12"}
    $md={{ vertical: false, height: 1, width: "100%", my: "$spacing16", mr: 0 }}
  />{" "}
            <Flex width={"100%"}>
              <Text variant="buttonLabel4" color={"$neutral2"}>
                Unstaked
              </Text>
              <Flex mt={"$spacing12"} flexDirection="column" gap={"$gap4"}>
                <TextWrapper>
                  {isGaugePosition ? "0.0000" : gaugeData.unstakedAmount0}{" "}
                  {position?.currency0Amount?.currency.symbol || "Token0"}
                </TextWrapper>
                <TextWrapper>
                  {isGaugePosition ? "0.0000" : gaugeData.unstakedAmount1}{" "}
                  {position?.currency1Amount?.currency.symbol || "Token1"}
                </TextWrapper>
              </Flex>

              <Flex mt={"$spacing18"} row gap={"$gap12"} $md={{ flexDirection: "column", width: "100%" }}>
                <Button
    className="button-clear"
    onClick={async () => {
      if (!gaugeData.canStake) return;
      try {
        await gaugeData.stakePosition(position?.tokenId || "");
      } catch (error) {
        console.error("Failed to stake position:", error);
      }
    }}
    style={{
      opacity: (isGaugePosition ? false : gaugeData.canStake) ? 1 : 0.5,
      cursor: (isGaugePosition ? false : gaugeData.canStake) ? "pointer" : "not-allowed"
    }}
    disabled={isGaugePosition || gaugeData.isStaked || !gaugeData.canStake}
  >
                  <Text variant="buttonLabel4">
                    {gaugeData.isLoading ? "Loading..." : isGaugePosition ? "Already staked" : gaugeData.isStaked ? "Fully staked" : gaugeData.needsApproval ? position?.version === ProtocolVersion.V3 ? "Approve & Stake" : "Approve & Stake (V2)" : gaugeData.canStake ? "Stake" : "No LP"}
                  </Text>
                </Button>
                <Button
    className="button-clear"
    onClick={async () => {
      if (!gaugeData.isStaked) return;
      try {
        await gaugeData.unstakePosition(position?.tokenId || "");
      } catch (error) {
        console.error("Failed to unstake position:", error);
      }
    }}
    style={{
      opacity: isGaugePosition || gaugeData.isStaked ? 1 : 0.5,
      cursor: isGaugePosition || gaugeData.isStaked ? "pointer" : "not-allowed"
    }}
    disabled={!isGaugePosition && !gaugeData.isStaked}
  >
                  <Text variant="buttonLabel4">
                    {gaugeData.isLoading ? "Loading..." : isGaugePosition || gaugeData.isStaked ? "Withdraw" : "Not Staked"}
                  </Text>
                </Button>
              </Flex>
            </Flex>
          </Flex>
        </GridItem>}
      {(gaugeData.gaugeAddress || true) && // TEMP: Always show for debugging
  <GridItem flexDirection="column" gap={"$spacing18"} $md={{ flexDirection: "column" }}>
          <Flex flexDirection="column" gap={"$gap12"}>
            <TextWrapper variant="buttonLabel4" color={"$neutral2"}>
              APR
            </TextWrapper>
            <TextWrapper>
              {gaugeData.isLoading ? "Loading..." : gaugeData.apr !== "N/A" && gaugeData.apr !== "0%" ? gaugeData.apr : "N/A"}
            </TextWrapper>
            {
    /* Show additional pool stats when APR is available */
  }
            {gaugeData.apr !== "N/A" && gaugeData.totalSupply !== "0" && <Flex flexDirection="column" gap={"$gap2"}>
                <Text variant="body4" color={"$neutral3"}>
                  Total Staked: {parseFloat(gaugeData.totalSupply).toFixed(2)} LP
                </Text>
                <Text variant="body4" color={"$neutral3"}>
                  Reward Rate: {parseFloat(gaugeData.rewardRate).toFixed(6)} ABX/s
                </Text>
              </Flex>}
          </Flex>{" "}
          <Separator display="none" height={1} width={"100%"} borderColor={"$surface3"} $md={{ display: "block" }} />
          <Flex flexDirection="column" gap={"$gap12"}>
            <TextWrapper variant="buttonLabel4" color={"$neutral2"}>
              Available Rewards
            </TextWrapper>
            <Flex flexDirection="column" gap={"$gap4"}>
              <TextWrapper>{parseFloat(gaugeData.pendingRewards).toFixed(6)} ABX</TextWrapper>
              {
    /* Show staked balance info */
  }
              {gaugeData.isStaked && <Text variant="body4" color={"$neutral3"}>
                  Staked: {parseFloat(gaugeData.rawStakedBalance).toFixed(6)} LP
                </Text>}
            </Flex>
            <Button
    className="button-clear"
    onClick={async () => {
      if (!position) {
        console.error("No position available for claiming");
        return;
      }
      const tokenIdOrEmpty = position.tokenId || "";
      try {
        await gaugeData.claimRewards(tokenIdOrEmpty);
      } catch (error) {
        console.error("Failed to claim rewards:", error);
      }
    }}
    style={{
      opacity: (isGaugePosition || gaugeData.isStaked) && parseFloat(gaugeData.pendingRewards) > 0 ? 1 : 0.5,
      cursor: (isGaugePosition || gaugeData.isStaked) && parseFloat(gaugeData.pendingRewards) > 0 ? "pointer" : "not-allowed"
    }}
    disabled={!isGaugePosition && !gaugeData.isStaked || parseFloat(gaugeData.pendingRewards) <= 0}
  >
              <Text variant="buttonLabel4">{parseFloat(gaugeData.pendingRewards) > 0 ? "Claim" : "No Rewards"}</Text>
            </Button>
          </Flex>
        </GridItem>}

      <GridItem
    flexDirection="column"
    gap={"$spacing18"}
    alignItems="flex-end"
    $md={{
      alignItems: "flex-start"
    }}
  >
        <Flex flexDirection="column">
          <Text variant="buttonLabel4" color={"$neutral2"}>
            Trading Fees
          </Text>
          <Flex
    alignItems="flex-end"
    $md={{ alignItems: "flex-start" }}
    mt={"$spacing12"}
    flexDirection="column"
    gap={"$gap4"}
  >
            <TextWrapper>
              {feeData.token0Fees} {position?.currency0Amount?.currency.symbol || "Token0"}
            </TextWrapper>
            <TextWrapper>
              {feeData.token1Fees} {position?.currency1Amount?.currency.symbol || "Token1"}
            </TextWrapper>
          </Flex>
        </Flex>

        <Button
    className="button-clear"
    onClick={async () => {
      if (!feeData.canCollect) return;
      try {
        await feeData.collectFees();
      } catch (error) {
        console.error("Failed to collect fees:", error);
        alert(`Failed to collect fees: ${error instanceof Error ? error.message : "Unknown error"}`);
      }
    }}
    style={{
      opacity: feeData.canCollect ? 1 : 0.5,
      cursor: feeData.canCollect ? "pointer" : "not-allowed"
    }}
    disabled={!feeData.canCollect}
  >
          <Text variant="buttonLabel4">{feeData.canCollect ? "Claim" : "No Fees"}</Text>
        </Button>
      </GridItem>
    </Flex>;
}
