"use strict";
import { RoundedLogo } from "components/Logo/LogoProvider";
import { MouseoverTooltip, TooltipSize } from "components/Tooltip";
import { useVotingRewards, formatRewardAmount } from "hooks/useVotingRewards";
import styled from "styled-components";
import { Flex, Text, useSporeColors } from "ui/src";
export default function RewardTokenAmountDetails({ lock, isLoading }) {
  const colors = useSporeColors();
  const { fees, bribes, canClaim, isLoading: rewardsLoading } = useVotingRewards(lock);
  const data = [
    // Fee rewards (from trading fees)
    ...fees.map((fee) => ({
      logo: RoundedLogo,
      amount: formatRewardAmount(fee.amount, fee.decimals),
      symbol: fee.symbol === "TOKEN" ? "ABX" : fee.symbol,
      // Default to ABX for now
      type: "Fees",
      tooltip: `~$${formatRewardAmount(fee.amount, fee.decimals)}`
    })),
    // Bribe rewards (incentives)  
    ...bribes.map((bribe) => ({
      logo: RoundedLogo,
      amount: formatRewardAmount(bribe.amount, bribe.decimals),
      symbol: bribe.symbol === "TOKEN" ? "ABX" : bribe.symbol,
      // Default to ABX for now
      type: "Incentive",
      tooltip: `~$${formatRewardAmount(bribe.amount, bribe.decimals)}`
    }))
  ];
  if (data.length === 0) {
    data.push(
      {
        logo: RoundedLogo,
        amount: "0",
        symbol: "ABX",
        type: "Fees",
        tooltip: "~$0.00"
      },
      {
        logo: RoundedLogo,
        amount: "0",
        symbol: "ETH",
        type: "Fees",
        tooltip: "~$0.00"
      },
      {
        logo: RoundedLogo,
        amount: "0",
        symbol: "ABX",
        type: "Incentive",
        tooltip: "~$0.00"
      }
    );
  }
  const ClaimButton = styled.button`
    all: unset;
    display: flex;
    padding: 5px 12px;
    border-radius: 30px;
    background-color: ${colors.surface2.val};
    borderradius: 10px;
    border: 1px solid ${colors.surface3.val};
    transition: all 0.2s ease;
    cursor: ${(props) => props.$canClaim ? "pointer" : "not-allowed"};
    opacity: ${(props) => props.$canClaim ? 1 : 0.6};
    &:hover {
      background-color: ${(props) => props.$canClaim ? colors.surface2Hovered.val : colors.surface2.val};
    }
  `;
  return <Flex
    className="right"
    flexDirection="column"
    alignItems="flex-end"
    gap={"$spacing18"}
    $md={{ alignItems: "flex-start" }}
  >
      <Flex flexDirection="column" alignItems="flex-end" gap={"$gap12"} $md={{ alignItems: "flex-start" }}>
        {data.map((item, index) => <Flex key={index} row alignItems="center" gap={"$gap8"} opacity={isLoading || rewardsLoading ? 0.6 : 1}>
            <MouseoverTooltip text={item.tooltip} size={TooltipSize.Max} placement="top">
              <Flex row alignItems="center" gap={"$gap8"}>
                <item.logo size={18} />
                <Text variant="body3">
                  {item.amount} {item.symbol}
                </Text>
              </Flex>
            </MouseoverTooltip>
            <Text
    backgroundColor={"$surface1"}
    py={"$padding4"}
    px={"$padding8"}
    borderRadius={"$rounded8"}
    variant={"body4"}
    borderWidth={1}
    borderColor={"$surface3"}
  >
              {item.type}
            </Text>
          </Flex>)}
      </Flex>
      <ClaimButton
    $canClaim={canClaim}
    disabled={!canClaim || rewardsLoading}
    onClick={() => {
      if (canClaim && !rewardsLoading) {
        console.log("\u{1F3AF} [VOTING REWARDS] Claiming rewards for lock:", lock?.id);
        alert("Claim functionality not yet implemented");
      }
    }}
  >
        <Text variant="body3" color={canClaim ? "$neutral1" : "$neutral2"}>
          {rewardsLoading ? "Loading..." : canClaim ? "Claim" : "No rewards"}
        </Text>
      </ClaimButton>
    </Flex>;
}
